(()=>{const root=document.querySelector('[data-language-menu]');const trigger=root.querySelector('button');const menu=root.querySelector('[role=menu]');const items=[...menu.querySelectorAll('[data-language]')];const pages={'zh-Hant':'index.html','zh-Hans':'zh-CN.html',en:'en.html',ja:'ja.html',ko:'ko.html'};const current=document.documentElement.lang;let manualChoice=false;let saved;try{saved=localStorage.getItem('vocalume-site-language')}catch{}if(saved&&saved!==current&&Object.hasOwn(pages,saved)){location.replace(pages[saved]+location.hash);return}if(!saved && ['/', '/index.html'].includes(location.pathname)) {
 const fallback=()=>{for(const value of navigator.languages||[navigator.language]){if(/^ko(?:-|$)/i.test(value))return 'ko';if(/^ja(?:-|$)/i.test(value))return 'ja';if(/^zh(?:-(?:CN|SG|Hans))(?:-|$)/i.test(value))return 'zh-Hans';if(/^zh(?:-|$)/i.test(value))return 'zh-Hant';if(/^en(?:-|$)/i.test(value))return 'en'}return 'en'};
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),1500);
 fetch('/api/site-language',{signal:controller.signal,cache:'no-store',credentials:'omit'})
 .then(response=>response.ok?response.json():Promise.reject(new Error('unavailable')))
 .then(data=>Object.hasOwn(pages,data.language)?data.language:fallback(),()=>fallback())
 .then(language=>{let latest;try{latest=localStorage.getItem('vocalume-site-language')}catch{}if(!manualChoice&&!latest&&language!==current)location.replace(pages[language]+location.search+location.hash)})
 .finally(()=>clearTimeout(timer));
}function close(focus=false){menu.hidden=true;trigger.setAttribute('aria-expanded','false');if(focus)trigger.focus()}function open(){menu.hidden=false;trigger.setAttribute('aria-expanded','true');items.find(x=>x.dataset.language===current).focus()}trigger.addEventListener('click',()=>menu.hidden?open():close());trigger.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();open()}});items.forEach(item=>item.addEventListener('click',()=>{const lang=item.dataset.language;manualChoice=true;try{localStorage.setItem('vocalume-site-language',lang)}catch{}if(lang===current){close(true);return}location.assign(pages[lang]+location.hash)}));root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close(true)}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&!menu.hidden){e.preventDefault();let i=items.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[i].focus()}});document.addEventListener('click',e=>{if(!root.contains(e.target))close()});root.addEventListener('focusout',event=>{if(!root.contains(event.relatedTarget))close()})})();